// Step Functions state machine mirroring the worker DAG (infra/dag.json, generated by
// `python -m replay_worker dag`; CI fails if it drifts), GPU stages as SageMaker
// Processing jobs, and the IAM the AWS providers will need. Every task is a placeholder:
// see docs/aws-integrations.md for what each needs before a deploy.
import { Duration, Stack, type StackProps } from "aws-cdk-lib";
import * as iam from "aws-cdk-lib/aws-iam";
import type * as s3 from "aws-cdk-lib/aws-s3";
import * as sfn from "aws-cdk-lib/aws-stepfunctions";
import * as tasks from "aws-cdk-lib/aws-stepfunctions-tasks";
import type { Construct } from "constructs";
import dag from "../dag.json";
import type { Tables } from "./data-stack";

interface DagStage {
  name: string;
  after: string[];
  resource: "gpu" | "cpu" | "io";
  fanout: boolean;
  cached: boolean;
  default: boolean;
}

export interface PipelineProps extends StackProps {
  bucket: s3.IBucket;
  tables: Tables;
}

export class PipelineStack extends Stack {
  constructor(scope: Construct, id: string, props: PipelineProps) {
    super(scope, id, props);
    const { bucket, tables } = props;

    // Role SageMaker Processing jobs run as: read/write the game's media in S3.
    const processingRole = new iam.Role(this, "ProcessingRole", {
      assumedBy: new iam.ServicePrincipal("sagemaker.amazonaws.com"),
      description: "Replay worker stages running as SageMaker Processing jobs",
    });
    bucket.grantReadWrite(processingRole);
    tables.jobs.grantReadWriteData(processingRole);

    // TODO: the worker container (services/worker) pushed to ECR; placeholder until then.
    const image =
      this.node.tryGetContext("workerImage") ??
      "ACCOUNT.dkr.ecr.REGION.amazonaws.com/replay-worker:latest";

    // Registry order is a valid topological order, so a chain respects every `after`.
    // ponytail: a straight chain; independent stages (calibrate || detect, tracks || crops
    // || events) could run in a Parallel state when stage latency matters.
    const stages = (dag as DagStage[]).filter((s) => s.default);
    const states = stages.map((s) => this.stageState(s, image, processingRole, bucket));
    let chain = sfn.Chain.start(states[0]);
    for (const st of states.slice(1)) chain = chain.next(st);

    const machine = new sfn.StateMachine(this, "ReplayPipeline", {
      definitionBody: sfn.DefinitionBody.fromChainable(chain),
      timeout: Duration.hours(2),
      comment: "Mirror of the services/worker DAG; input {game_id, s3_prefix}",
    });
    tables.jobs.grantReadWriteData(machine);

    // What the API's AWS providers call: Bedrock (LLM, labeler, query, embeddings), Polly
    // (TTS), Rekognition (opt-in faces), the data stores and the state machine. Attached
    // to whatever runs the API once that is decided (Lambda / App Runner / ECS).
    new iam.ManagedPolicy(this, "ApiProvidersPolicy", {
      description: "Replay API AWS providers (providers/aws.py)",
      statements: [
        new iam.PolicyStatement({
          actions: [
            "bedrock:InvokeModel",
            "bedrock:InvokeModelWithResponseStream",
            "bedrock:Converse",
            "bedrock:ConverseStream",
          ],
          // TODO: scope to the chosen Nova / embedding model ARNs
          resources: ["*"],
        }),
        new iam.PolicyStatement({ actions: ["polly:SynthesizeSpeech"], resources: ["*"] }),
        new iam.PolicyStatement({
          actions: [
            "rekognition:CreateCollection",
            "rekognition:IndexFaces",
            "rekognition:SearchFacesByImage",
            "rekognition:DeleteFaces",
          ],
          // TODO: scope to collection ARNs once the naming is fixed
          resources: ["*"],
        }),
        new iam.PolicyStatement({
          actions: ["states:StartExecution", "states:DescribeExecution"],
          resources: [machine.stateMachineArn],
        }),
        new iam.PolicyStatement({
          actions: ["s3:GetObject", "s3:PutObject", "s3:ListBucket"],
          resources: [bucket.bucketArn, bucket.arnForObjects("*")],
        }),
        new iam.PolicyStatement({
          actions: [
            "dynamodb:GetItem",
            "dynamodb:PutItem",
            "dynamodb:UpdateItem",
            "dynamodb:Query",
          ],
          resources: [tables.games, tables.profiles, tables.jobs].flatMap((t) => [
            t.tableArn,
            `${t.tableArn}/index/*`,
          ]),
        }),
      ],
    });
  }

  private stageState(
    s: DagStage,
    image: string,
    role: iam.IRole,
    bucket: s3.IBucket,
  ): sfn.IChainable {
    const id = `Stage_${s.name}`;
    if (s.resource !== "gpu") {
      // TODO: CPU/IO stages → a CPU SageMaker Processing job or an ECS task running
      // `python -m replay_worker run --stages <name>` against the S3 game prefix.
      const pass = new sfn.Pass(this, id, {
        comment: `placeholder: worker stage '${s.name}' (${s.resource})`,
        resultPath: sfn.JsonPath.DISCARD,
      });
      return s.fanout ? this.fanOut(s, pass) : pass;
    }
    // TODO: `.sync` (wait for completion) needs the optimized integration
    // `arn:aws:states:::sagemaker:createProcessingJob.sync` via sfn.CustomState; job
    // names must be unique per account, so add the execution name once that lands.
    const job = new tasks.CallAwsService(this, id, {
      comment: `worker stage '${s.name}' on a GPU instance`,
      service: "sagemaker",
      action: "createProcessingJob",
      iamResources: ["*"],
      additionalIamStatements: [
        new iam.PolicyStatement({ actions: ["iam:PassRole"], resources: [role.roleArn] }),
      ],
      parameters: {
        ProcessingJobName: sfn.JsonPath.format(
          "replay-{}-{}",
          sfn.JsonPath.stringAt("$.game_id"),
          s.name,
        ),
        RoleArn: role.roleArn,
        AppSpecification: {
          ImageUri: image,
          ContainerEntrypoint: ["python", "-m", "replay_worker", "run", "/opt/ml/processing/game"],
          ContainerArguments: ["--stages", s.name],
        },
        ProcessingResources: {
          ClusterConfig: { InstanceCount: 1, InstanceType: "ml.g5.xlarge", VolumeSizeInGB: 50 },
        },
        ProcessingInputs: [
          {
            InputName: "game",
            S3Input: {
              S3Uri: sfn.JsonPath.format(
                `s3://${bucket.bucketName}/games/{}/`,
                sfn.JsonPath.stringAt("$.game_id"),
              ),
              LocalPath: "/opt/ml/processing/game",
              S3DataType: "S3Prefix",
              S3InputMode: "File",
            },
          },
        ],
        ProcessingOutputConfig: {
          Outputs: [
            {
              OutputName: "game",
              S3Output: {
                S3Uri: sfn.JsonPath.format(
                  `s3://${bucket.bucketName}/games/{}/`,
                  sfn.JsonPath.stringAt("$.game_id"),
                ),
                LocalPath: "/opt/ml/processing/game",
                S3UploadMode: "EndOfJob",
              },
            },
          ],
        },
      },
      resultPath: sfn.JsonPath.DISCARD,
    });
    return s.fanout ? this.fanOut(s, job) : job;
  }

  /** Per-player / per-play / per-angle stages: one iteration per item. */
  private fanOut(s: DagStage, body: sfn.IChainable): sfn.IChainable {
    const map = new sfn.Map(this, `FanOut_${s.name}`, {
      itemsPath: sfn.JsonPath.stringAt(`$.items.${s.name}`),
      maxConcurrency: s.resource === "gpu" ? 1 : 4,
      resultPath: sfn.JsonPath.DISCARD,
    });
    map.itemProcessor(body);
    return map;
  }
}
